# i: K son of T, P wife of K -> P is son's wife of T. ii: same. iii, iv: P is T's mother/child, not daughter-in-law.
res={'i':True,'ii':True,'iii':False,'iv':False}
opts={'A':{'ii'},'B':{'iii','iv'},'C':{'i'},'D':{'i','ii'}}
true={k for k,v in res.items() if v}
assert opts['D']==true
assert all(opts[k]!=true for k in 'ABC')

F,S,V,G=1,2,4,8
def has(S_,f): return any(f(r) for r in S_)
def models():
    for bits in range(1,1<<16):
        X=[r for r in range(16) if bits>>r&1]
        if not has(X,lambda r:r&F and not r&S) and has(X,lambda r:r&S and r&V) and has(X,lambda r:r&V and r&G):
            yield X
ms=list(models())
c1=lambda X:not has(X,lambda r:r&V and not r&S)
c2=lambda X:has(X,lambda r:r&S and r&G)
assert (all(c1(X) for X in ms),all(c2(X) for X in ms))==(False,False)

